<script setup>
import { computed, ref, watch } from 'vue'
const props=defineProps({rows:{type:Array,required:true},workTitle:{type:Function,required:true},inSpec:{type:Function,required:true}});const page=ref(1),size=8;const pages=computed(()=>Math.max(1,Math.ceil(props.rows.length/size)));const visible=computed(()=>[...props.rows].reverse().slice((page.value-1)*size,page.value*size));watch(()=>props.rows,()=>page.value=1)
function stamp(v){return v.replace('T',' ')}
</script>
<template><section class="panel table-panel"><div class="heading"><div><h2>세부 데이터</h2><p>조회 조건에 해당하는 {{ rows.length }}건의 측정 데이터</p></div></div><div class="wrap"><table><thead><tr><th>측정 일시</th><th>작업 Title</th><th>설비 / 챔버</th><th>Side</th><th>PPID</th><th>FOUP ID</th><th>Slot</th><th>AVG</th><th>Range</th><th>Stress</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td>{{ stamp(row.time) }}</td><td class="work">{{ workTitle(row) }}</td><td class="strong">{{ row.eqpid }} / {{ row.chid }}</td><td>{{ row.side }}</td><td>{{ row.ppid }}</td><td>{{ row.foupid }}</td><td>{{ row.slotid }}</td><td class="number" :class="inSpec('avg',row.avg)?'spec-in':'spec-out'">{{ row.avg.toFixed(1) }}</td><td class="number" :class="inSpec('range',row.range)?'spec-in':'spec-out'">{{ row.range.toFixed(1) }}</td><td class="number" :class="inSpec('stress',row.stress)?'spec-in':'spec-out'">{{ row.stress.toFixed(1) }}</td></tr><tr v-if="!visible.length"><td colspan="10" class="empty">조회 조건에 맞는 데이터가 없습니다.</td></tr></tbody></table></div><footer><span>전체 {{ rows.length }}건 중 {{ visible.length }}건 표시</span><div><button :disabled="page===1" @click="page--">이전</button><b>{{ page }} / {{ pages }}</b><button :disabled="page===pages" @click="page++">다음</button></div></footer></section></template>
<style scoped>.table-panel{overflow:hidden}.heading{padding:18px 20px 14px}.heading h2{font-size:15px}.heading p{margin-top:3px;color:var(--muted);font-size:10px}.wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:10px}th{padding:10px 13px;color:#70849a;background:#101b29;border-block:1px solid var(--border);font-size:8px;letter-spacing:.06em;text-align:left}td{padding:11px 13px;color:#92a4b6;border-bottom:1px solid rgba(50,69,91,.5)}tbody tr:hover{background:rgba(70,105,142,.07)}.strong{color:#d3dfeb;font-weight:650}.work{color:#e5b16d}.number{font-variant-numeric:tabular-nums;font-weight:700}.spec-in{color:#54d29d}.spec-out{color:#f07178}.empty{height:90px;text-align:center}footer{display:flex;justify-content:space-between;align-items:center;padding:12px 18px;color:#657a90;font-size:9px}footer div{display:flex;align-items:center;gap:8px}footer button{padding:5px 8px;color:#8195a9;background:#101b29;border:1px solid var(--border);border-radius:5px;font-size:8px}footer button:disabled{opacity:.3}footer b{color:#a4b5c6;font-size:8px}</style>
